  styles: `
    main { max-width: 60rem; margin: 0 auto; padding: 1.5rem; font-family: system-ui, sans-serif; }
    app-dashboard-filters { margin-bottom: 1.5rem; }
    app-account-summary { margin-bottom: 1.5rem; }
