import { ChangeDetectionStrategy, Component, ElementRef, computed, input, output, signal, viewChild } from '@angular/core';
import { CdkConnectedOverlay, CdkOverlayOrigin } from '@angular/cdk/overlay';
import { CdkTrapFocus } from '@angular/cdk/a11y';
import { MatCalendar, MatCalendarCellClassFunction } from '@angular/material/datepicker';
import { addDays, format, isMonday, parseISO } from 'date-fns';
import { WeekRange } from '../../../core/models';

@Component({
  selector: 'app-week-picker',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CdkConnectedOverlay, CdkOverlayOrigin, CdkTrapFocus, MatCalendar],
  template: `
    <button #trigger type="button" cdkOverlayOrigin #origin="cdkOverlayOrigin" aria-haspopup="dialog" [attr.aria-expanded]="open()"
      [attr.aria-label]="label() + ', choose week'" [disabled]="disabled()" (click)="open.set(true)">{{ label() }}</button>
    <ng-template cdkConnectedOverlay [cdkConnectedOverlayOrigin]="origin" [cdkConnectedOverlayOpen]="open()"
      (overlayKeydown)="onKey($event)" (overlayOutsideClick)="close()" (attach)="focusCalendar()">
      <div role="dialog" aria-label="Choose week" cdkTrapFocus>
        <mat-calendar [minDate]="min()" [maxDate]="max()" [dateFilter]="filter" [dateClass]="dateClass" [selected]="selected()" [startAt]="selected()" (selectedChange)="choose($event)" />
        <p>Weeks run Monday to Sunday.</p>
        <p>{{ rangeText() }}</p>
      </div>
    </ng-template>
  `,
})
export class WeekPicker {
  readonly week = input.required<WeekRange>();
  readonly earliestWeek = input.required<string>();
  readonly latestCompleteWeek = input.required<string>();
  readonly weekSelected = output<string>();
  protected readonly open = signal(false);
  private readonly trigger = viewChild.required<ElementRef<HTMLButtonElement>>('trigger');
  private readonly calendar = viewChild(MatCalendar);
  protected readonly min = computed(() => parseISO(this.earliestWeek()));
  protected readonly max = computed(() => parseISO(this.latestCompleteWeek()));
  protected readonly selected = computed(() => parseISO(this.week().start));
  protected readonly disabled = computed(() => this.earliestWeek() === this.latestCompleteWeek());
  protected readonly label = computed(() => `${format(parseISO(this.week().start), 'EEE MMM d')} – ${format(parseISO(this.week().end), 'EEE MMM d, yyyy')}`);
  protected readonly rangeText = computed(() => {
    const a = this.min(); const b = this.max();
    const same = a.getFullYear() === b.getFullYear();
    return `Weeks from ${format(a, same ? 'EEE MMM d' : 'EEE MMM d, yyyy')} to ${format(b, 'EEE MMM d, yyyy')}`;
  });
  protected readonly filter = (d: Date | null) => d !== null && isMonday(d) && d >= this.min() && d <= this.max();
  protected readonly dateClass: MatCalendarCellClassFunction<Date> = (d, view) => {
    const s = this.selected();
    return view === 'month' && d > s && d <= addDays(s, 6) ? 'week-rest' : '';
  };
  protected focusCalendar(): void { setTimeout(() => this.calendar()?.focusActiveCell()); }
